shared_html.shared_css:
/* ---------- shared header / footer ---------- */

.site-nav,
.site-footer {
  color: var(--text);
  font-family: "Inter", system-ui, sans-serif;
}

/* HEADER ------------------------------------------------------- */

.site-nav {
  background: var(--bg);
  padding: 2.25rem clamp(1.25rem, 4vw, 3.5rem) 0;
}

.site-nav__inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 2rem;
  max-width: 1320px;
  margin: 0 auto;
}

.site-nav__brand {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
  line-height: 1.1;
}

.site-nav__kicker {
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin-bottom: 0.6rem;
}

.site-nav__wordmark {
  font-family: "Shippori Mincho", "Noto Serif JP", serif;
  font-weight: 700;
  font-size: clamp(1.85rem, 3.4vw, 2.6rem);
  letter-spacing: 0.01em;
  color: var(--primary);
}

.site-nav__sub {
  margin-top: 0.45rem;
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text);
  opacity: 0.65;
}

.site-nav__links ol {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.25rem 1.5rem;
}

.site-nav__links a {
  display: inline-flex;
  align-items: baseline;
  gap: 0.45rem;
  text-decoration: none;
  color: var(--text);
  font-size: 0.84rem;
  letter-spacing: 0.04em;
  padding: 0.35rem 0;
  border-bottom: 1px solid transparent;
  transition: color .2s ease, border-color .2s ease;
}

.site-nav__links a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.site-nav__links .num {
  font-family: "Shippori Mincho", serif;
  font-size: 0.7rem;
  color: var(--text-emphasis);
  letter-spacing: 0.1em;
}

.site-nav__rule {
  max-width: 1320px;
  margin: 1.75rem auto 0;
  height: 1px;
  background: var(--ornament);
  opacity: 0.85;
  position: relative;
}

.site-nav__rule::after {
  content: "";
  position: absolute;
  right: 0;
  top: -2px;
  width: 64px;
  height: 5px;
  background: var(--accent);
}

@media (max-width: 760px) {
  .site-nav__inner {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }
  .site-nav__links ol { justify-content: flex-start; }
}

/* FOOTER ------------------------------------------------------- */

.site-footer {
  margin-top: 6rem;
  padding: 3.5rem clamp(1.25rem, 4vw, 3.5rem) 2rem;
  background: var(--bg);
  border-top: 1px solid var(--ornament);
  position: relative;
}

.site-footer::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 0;
  width: 96px;
  height: 3px;
  background: var(--accent);
}

.site-footer__inner {
  max-width: 1320px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: auto minmax(0, 1.4fr) minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4rem);
  align-items: start;
}

.site-footer__seal {
  color: var(--accent);
  display: flex;
  align-items: flex-start;
  justify-content: center;
}

.site-footer__title {
  font-family: "Shippori Mincho", serif;
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0 0 1rem;
  color: var(--primary);
  letter-spacing: 0.02em;
}

.site-footer__addr,
.site-footer__contact {
  margin: 0 0 1rem;
  font-size: 0.86rem;
  line-height: 1.7;
  color: var(--text);
}

.site-footer__contact {
  color: var(--text-emphasis);
}

.site-footer__navhead {
  font-family: "Shippori Mincho", serif;
  font-size: 0.78rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin: 0 0 1rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid var(--ornament);
}

.site-footer__nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.site-footer__nav a {
  text-decoration: none;
  color: var(--text);
  font-size: 0.86rem;
  letter-spacing: 0.02em;
  border-bottom: 1px solid transparent;
  padding-bottom: 1px;
  transition: color .2s, border-color .2s;
}

.site-footer__nav a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.site-footer__meta {
  max-width: 1320px;
  margin: 3rem auto 0;
  padding-top: 1.25rem;
  border-top: 1px solid var(--ornament);
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 2rem;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  color: var(--text);
  opacity: 0.7;
}

@media (max-width: 760px) {
  .site-footer__inner {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .site-footer__seal { justify-content: flex-start; }
}
